#!/usr/bin/env node
// Diagnose local build residue, and remove it only when asked
// (audit 2026-10-07 P3-3).
//
// Old release trees, caches and generated output make local audits slow and
// blur which files are evidence. This prints every known residue location,
// its size, and its class:
//
//   build-output   regenerated by a build or test run; safe to remove
//   downloads      re-downloaded on demand (llama.cpp binaries and archives)
//   release        installers from electron-builder; keep anything you still
//                  need to compare against or ship
//
// It changes nothing unless you pass --remove with one or more classes:
//
//   pnpm clean:diagnose                          # report only
//   pnpm clean:diagnose --remove=build-output    # delete regenerable output
//   pnpm clean:diagnose --remove=build-output,downloads
//
// Release evidence that matters lives on GitHub Releases (installers,
// SHA256SUMS.txt, SBOM, provenance attestations), never in a local release/.

import { existsSync, readdirSync, rmSync, statSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');

const PACKAGES = existsSync(join(ROOT, 'packages'))
  ? readdirSync(join(ROOT, 'packages')).map((p) => `packages/${p}`)
  : [];

/** Residue locations, relative to the repo root, by class. */
export const RESIDUE = {
  'build-output': [
    'coverage',
    'apps/desktop/out',
    'apps/desktop/test-results',
    'apps/desktop/playwright-report',
    'apps/desktop/.eslintcache',
    ...PACKAGES.map((p) => `${p}/dist`),
  ],
  downloads: ['.llama-cache', 'apps/desktop/resources/llama-server'],
  release: ['release'],
};

function sizeOf(path) {
  const st = statSync(path, { throwIfNoEntry: false });
  if (!st) return 0;
  if (!st.isDirectory()) return st.size;
  let total = 0;
  for (const entry of readdirSync(path, { withFileTypes: true })) {
    if (entry.isSymbolicLink()) continue;
    total += sizeOf(join(path, entry.name));
  }
  return total;
}

function human(bytes) {
  if (bytes >= 1024 ** 3) return `${(bytes / 1024 ** 3).toFixed(1)} GB`;
  if (bytes >= 1024 ** 2) return `${(bytes / 1024 ** 2).toFixed(1)} MB`;
  if (bytes >= 1024) return `${(bytes / 1024).toFixed(0)} KB`;
  return `${bytes} B`;
}

/** Pure: which existing paths a --remove request would delete. */
export function plan(root, classes) {
  const unknown = classes.filter((c) => !(c in RESIDUE));
  if (unknown.length > 0) {
    throw new Error(
      `unknown class(es): ${unknown.join(', ')}; expected ${Object.keys(RESIDUE).join(', ')}`,
    );
  }
  return classes.flatMap((c) => RESIDUE[c].map((p) => join(root, p)).filter((p) => existsSync(p)));
}

function main() {
  const removeArg = process.argv.find((a) => a.startsWith('--remove='));
  const classes = removeArg ? removeArg.slice('--remove='.length).split(',').filter(Boolean) : [];

  let total = 0;
  for (const [cls, paths] of Object.entries(RESIDUE)) {
    for (const p of paths) {
      const abs = join(ROOT, p);
      if (!existsSync(abs)) continue;
      const size = sizeOf(abs);
      total += size;
      console.log(`${cls.padEnd(13)} ${human(size).padStart(9)}  ${p}`);
    }
  }
  console.log(`${'total'.padEnd(13)} ${human(total).padStart(9)}`);

  if (classes.length === 0) {
    console.log('\nNothing removed. Pass --remove=<class>[,<class>] to delete a class.');
    return;
  }
  for (const abs of plan(ROOT, classes)) {
    rmSync(abs, { recursive: true, force: true });
    console.log(`removed ${relative(ROOT, abs)}`);
  }
}

const isMain =
  process.argv[1] && resolve(process.argv[1]) === resolve(fileURLToPath(import.meta.url));
if (isMain) {
  try {
    main();
  } catch (err) {
    console.error(`clean:diagnose: ${err.message}`);
    process.exit(2);
  }
}
